entries[33878] = { ["name"] = "Zerfleischen", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Bärengestalt\nZerfleischt das Ziel, fügt ihm 280% Waffenschaden zu [ Infizierte Wunden : verringert sein Bewegungstempo 12 Sek. lang um 50% ] und erzeugt [ Seele des Waldes : 6.5 / 5] Wut." }
entries[33886] = { ["name"] = "Rasche Verjüngung", ["text"] = "Verringert die globale Abklingzeit Eures Zaubers 'Verjüngung' um 0.5 Sek." }
entries[33891] = { ["name"] = "Inkarnation: Baum des Lebens", ["text"] = "Sofort 3 min Abklingzeit\nVerwandelt Euch in die Gestalt eines Baums des Lebens, wodurch sich Eure Heilung um 15% und Eure Rüstung um 120% erhöhen. Beschützt Euch außerdem vor Verwandlungseffekten. Darüber hinaus werden in dieser Gestalt einige Eurer Zauber verstärkt. Hält 30 Sek. lang an.\n\nWährend der Effektdauer könnt Ihr Euch beliebig in diese Gestalt verwandeln.\n\nVerstärkte Zauber: 'Blühendes Leben', 'Wildwuchs', 'Nachwachsen', 'Wucherwurzeln'" }
entries[33895] = { ["name"] = "Sprengladung aktivieren", ["text"] = "Wirken in 2 sek.\nErschafft eine Sprengladung." }
entries[33896] = { ["name"] = "Verzweifelte Verteidigung", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde wurzelt sich selbst fest, schirmt sich von allen Angriffen ab und wird mehr und mehr wütend, je länger er angegriffen wird. Jeder Schlag erhöht den Effekt der Wut." }
entries[33898] = { ["name"] = "Verzweifelte Wut", ["text"] = "Sofort\nErhöht 2 Min. lang das Angriffstempo des Zaubernden um 5% und den verursachten körperlichen Schaden um 10%." }
