entries[33907] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, Naturschaden zufügen. Hält 10 Min. lang an." }
entries[33908] = { ["name"] = "Brennende Stacheln", ["text"] = "30 Meter Reichweite\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer Feuerschaden zufügen. Hält bis Abbruch lang an." }
entries[33909] = { ["name"] = "Überragen", ["text"] = "Sofort\nErhöht den vom Zaubernden verursachten körperlichen Schaden bis Abbruch lang um 10%." }
entries[33910] = { ["name"] = "Andere Heilen", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 4 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[33911] = { ["name"] = "Rüstung zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nHackt nach der Rüstung des Feindes und verringert sie pro Anwendung von 'Rüstung zerfetzen'. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[33912] = { ["name"] = "Zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[33913] = { ["name"] = "Seelenbrand", ["text"] = "40 Meter Reichweite\nSofort\nFügt einem Gegner 6 Sek. lang insgesamt 1500 Feuerschaden zu, hindert ihn daran, Zauber zu wirken, und verringert den von ihm zugefügten körperlichen Schaden um 50%." }
entries[33914] = { ["name"] = "Schattenschlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nGreift einen Gegner an und fügt ihm Waffenschaden sowie zusätzlichen Bonusschaden zu." }
