entries[33916] = { ["name"] = "Entzug der Leere", ["text"] = "25 Mana\nWirken in 3 sek.\nEntzieht allen Gegnern in einem Radius von 10 Metern Gesundheit." }
entries[33917] = { ["name"] = "Zerfleischen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt, Bärengestalt\nZerfleischt das Ziel, was ihm körperlichen Schaden zufügt [ Infizierte Wunden : und das Bewegungstempo des Ziels 12 Sek. lang um 50% verringert ]. Der Schaden hängt von der Tiergestalt ab. Erzeugt [ Seele des Waldes : 7.5 / 5] Wut in Bärengestalt und gewährt 1 Combopunkt in Katzengestalt." }
entries[33918] = { ["name"] = "Kristallkanalisierung" }
entries[33919] = { ["name"] = "Erdbeben", ["text"] = "Wirken in 1 sek. 6 sek. Abklingzeit\nFügt nahen Gegnern regelmäßig körperlichen Schaden zu, betäubt sie 3 Sek. lang." }
entries[33923] = { ["name"] = "Überschallknall", ["text"] = "Wirken in 5 sek. 7 sek. Abklingzeit\nVerursacht einen massiven Ausbruch von Schallenergie, die Gegnern in der Nähe Naturschaden zufügt und anschließend 9 Sek. lang alle 3 Sek. zusätzlichen Naturschaden verursacht. Unter dem Einfluss von 'Überschallknall' verringert sich das gegnerische Bewegungstempo um 90%." }
entries[33924] = { ["name"] = "Furcht", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nErfüllt einen Gegner mit Furcht, woraufhin er 4 Sek. lang vor Angst flieht. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[33925] = { ["name"] = "Phantomstoß", ["text"] = "20 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nAngriffs- und Zaubertempo um 50% verlangsamt.\nAlle 3 Sek. Naturschaden verursacht.\nHält 12 Sek. an." }
