entries[33943] = { ["name"] = "Fluggestalt", ["text"] = "5.6% von Grundmana\nSofort\nVerwandelt Euch in eine Fluggestalt, erhöht das Bewegungstempo um 150% und ermöglicht es Euch, zu fliegen. Kann nicht im Kampf eingesetzt werden.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
