entries[33964] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 150% des normalen Waffenschadens. Zusätzlich stellen die nächsten 5 erfolgreichen Nahkampfangriffe 0 Gesundheit wieder her. Dieser Effekt hält 10 Sek. lang an." }
entries[33965] = { ["name"] = "Umsehen", ["text"] = "Sofort\nVerursacht, dass der Zaubernde sich 8 Sek. lang vorsichtig umsieht." }
entries[33966] = { ["name"] = "Mörderischen Schlammling beschwören", ["text"] = "Wirken in 3 sek.\nBeschwört einen Schlammlingverbündeten." }
entries[33967] = { ["name"] = "Donnerknall", ["text"] = "Sofort\nFügt nahen Gegnern Naturschaden zu, erhöht die Zeit zwischen ihren Angriffen und verringert ihr Bewegungstempo. Hält 10 Sek. lang an." }
entries[33968] = { ["name"] = "Ätzender Nebel", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nFügt nahen Gegnern alle 2 Sek. Naturschaden zu und verringert ihre Rüstung. Hält 15 Sek. lang an." }
entries[33969] = { ["name"] = "Absaugender Blitz", ["text"] = "565 Mana 30 Meter Reichweite\nWirken in 3 sek.\nFügt dem Gegner 24 bis 29 Schattenschaden zu. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
entries[33970] = { ["name"] = "Anstürmen", ["text"] = "40 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, fügt ihm sowie seinen nahen Verbündeten Schaden zu und stößt alle betroffenen Ziele zurück." }
