entries[34004] = { ["name"] = "Umhang - Große Beweglichkeit", ["text"] = "Wirken in 1.5 sek.\nBenötigt Umhang\nTools: Runenverzierte Kupferrute\nReagenzien:\nGroße Planaressenz , Arkaner Staub (4), Urluft\nEinen Umhang dauerhaft verzaubern, sodass die Beweglichkeit um 12 erhöht wird." }
entries[34007] = { ["name"] = "Stiefel - Schnelligkeit der Katze", ["text"] = "Wirken in 1.5 sek.\nBenötigt Stiefel\nTools: Runenverzierte Kupferrute\nReagenzien:\nGroßer Prismasplitter (8), Urluft (8)\nStiefel dauerhaft verzaubern, sodass die Beweglichkeit um 6 und das Bewegungstempo um 8% erhöht wird." }
