entries[34009] = { ["name"] = "Schild - Erhebliche Ausdauer", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Kupferrute\nReagenzien:\nArkaner Staub (15)\nEinen Schild dauerhaft verzaubern, sodass die Ausdauer um 18 erhöht wird." }
entries[34010] = { ["name"] = "Waffe - Erhebliche Heilung", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Kupferrute\nReagenzien:\nGroßer Prismasplitter (8), Urwasser (8), Urleben (8)\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Zaubermacht um 40 erhöht wird." }
